package com.commercecore.cart;
import com.commercecore.common.exception.ApiException;import com.commercecore.product.*;import com.commercecore.promotion.*;import com.commercecore.user.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.util.*;
@Service public class CartService{
 private final CartRepository carts;private final CartItemRepository items;private final UserAccountRepository users;private final SellableItemResolver resolver;private final PromotionService promotions;
 public CartService(CartRepository c,CartItemRepository i,UserAccountRepository u,SellableItemResolver r,PromotionService p){carts=c;items=i;users=u;resolver=r;promotions=p;}
 @Transactional public CartDtos.CartResponse get(UUID userId){return response(cart(userId));}
 @Transactional public CartDtos.CartResponse add(UUID userId,CartDtos.AddItemRequest request){Cart cart=cart(userId);SellableItemResolver.Selection selection=resolver.resolve(request.productId(),request.variantId(),request.quantity(),true);Optional<CartItem> existing=selection.variant()==null?items.findByCartIdAndProductIdAndVariantIsNull(cart.getId(),selection.product().getId()):items.findByCartIdAndVariantId(cart.getId(),selection.variant().getId());
  if(existing.isPresent()){int next;try{next=Math.addExact(existing.get().getQuantity(),request.quantity());}catch(ArithmeticException e){throw invalidQuantity();}resolver.resolve(request.productId(),request.variantId(),next,true);try{existing.get().changeQuantity(next);}catch(IllegalArgumentException e){throw invalidQuantity();}}
  else try{items.saveAndFlush(new CartItem(cart,selection.product(),selection.variant(),request.quantity()));}catch(DataIntegrityViolationException e){throw error(HttpStatus.CONFLICT,"CART_ITEM_CONFLICT","Cart item conflicts with existing data.");}
  cart.markChanged();return response(cart);
 }
 @Transactional public CartDtos.CartResponse update(UUID userId,UUID itemId,CartDtos.UpdateItemRequest request){CartItem item=owned(itemId,userId);resolver.resolve(item.getProduct().getId(),item.getVariant()==null?null:item.getVariant().getId(),request.quantity(),true);try{item.changeQuantity(request.quantity());}catch(IllegalArgumentException e){throw invalidQuantity();}item.getCart().markChanged();return response(item.getCart());}
 @Transactional public CartDtos.CartResponse remove(UUID userId,UUID itemId){CartItem item=owned(itemId,userId);Cart cart=item.getCart();items.delete(item);items.flush();cart.markChanged();return response(cart);}
 @Transactional public CartDtos.CartResponse clear(UUID userId){Cart cart=cart(userId);items.deleteAllByCartId(cart.getId());items.flush();cart.markChanged();return response(cart);}
 @Transactional public CartDtos.CartResponse applyPromotion(UUID userId,String code){Cart cart=cart(userId);Promotion promotion=promotions.findByCode(code);Pricing pricing=pricing(cart);PromotionService.Evaluation evaluation=promotions.evaluate(promotion,userId,pricing.promotionLines());if(!evaluation.valid())throw promotions.evaluationError(evaluation);cart.apply(promotion);return response(cart);}
 @Transactional public CartDtos.CartResponse removePromotion(UUID userId){Cart cart=cart(userId);cart.removePromotion();return response(cart);}
 @Transactional public Cart lockForCheckout(UUID userId){return carts.findLockedByUserId(userId).orElseThrow(()->error(HttpStatus.CONFLICT,"EMPTY_CART","Cart is empty."));}
 @Transactional public CheckoutSnapshot checkoutSnapshot(Cart cart){List<CheckoutLine> checkoutLines=new ArrayList<>();List<PromotionService.PricingLine> promoLines=new ArrayList<>();BigDecimal subtotal=BigDecimal.ZERO;for(CartItem item:items.findAllByCartIdOrderByCreatedAtAsc(cart.getId())){SellableItemResolver.Selection selected=resolver.resolve(item.getProduct().getId(),item.getVariant()==null?null:item.getVariant().getId(),item.getQuantity(),true);BigDecimal unit=money(selected.unitPrice());BigDecimal line=money(unit.multiply(BigDecimal.valueOf(item.getQuantity())));checkoutLines.add(new CheckoutLine(item,selected,unit,line));promoLines.add(new PromotionService.PricingLine(selected.product(),line));subtotal=subtotal.add(line);}if(checkoutLines.isEmpty())throw error(HttpStatus.CONFLICT,"EMPTY_CART","Cart is empty.");PromotionService.Evaluation evaluation=null;if(cart.getAppliedPromotion()!=null){evaluation=promotions.evaluate(cart.getAppliedPromotion(),cart.getUser().getId(),promoLines);if(!evaluation.valid())throw promotions.evaluationError(evaluation);}BigDecimal discount=evaluation==null?money(BigDecimal.ZERO):evaluation.discount();return new CheckoutSnapshot(cart,List.copyOf(checkoutLines),money(subtotal),discount,money(subtotal.subtract(discount)),cart.getAppliedPromotion(),evaluation!=null&&evaluation.freeShipping());}
 @Transactional public void clearAfterCheckout(Cart cart){items.deleteAllByCartId(cart.getId());cart.removePromotion();cart.markChanged();}
 private Cart cart(UUID userId){return carts.findByUserId(userId).orElseGet(()->{UserAccount user=users.findById(userId).orElseThrow(()->error(HttpStatus.NOT_FOUND,"USER_NOT_FOUND","User was not found."));try{return carts.saveAndFlush(new Cart(user));}catch(DataIntegrityViolationException race){return carts.findByUserId(userId).orElseThrow();}});}
 private CartItem owned(UUID itemId,UUID userId){return items.findByIdAndCartUserId(itemId,userId).orElseThrow(()->error(HttpStatus.NOT_FOUND,"CART_ITEM_NOT_FOUND","Cart item was not found."));}
 private CartDtos.CartResponse response(Cart cart){Pricing pricing=pricing(cart);PromotionService.Evaluation evaluation=null;CartDtos.PromotionPricing promotionDto=null;
  if(cart.getAppliedPromotion()!=null){evaluation=promotions.evaluate(cart.getAppliedPromotion(),cart.getUser().getId(),pricing.promotionLines());promotionDto=new CartDtos.PromotionPricing(cart.getAppliedPromotion().getId(),cart.getAppliedPromotion().getCode(),evaluation.valid(),evaluation.errorCode(),evaluation.eligibleSubtotal(),evaluation.discount(),evaluation.freeShipping());}
  BigDecimal discount=evaluation!=null&&evaluation.valid()?evaluation.discount():money(BigDecimal.ZERO);boolean free=evaluation!=null&&evaluation.valid()&&evaluation.freeShipping();BigDecimal finalTotal=pricing.subtotal().subtract(discount).max(BigDecimal.ZERO).setScale(2,RoundingMode.HALF_UP);boolean ready=!pricing.lines().isEmpty()&&pricing.lines().stream().allMatch(l->l.status()==CartLineStatus.AVAILABLE)&&(evaluation==null||evaluation.valid());
  return new CartDtos.CartResponse(cart.getId(),pricing.lines(),pricing.subtotal(),discount,finalTotal,free,promotionDto,ready,cart.getUpdatedAt());}
 private Pricing pricing(Cart cart){List<CartDtos.CartLine> lines=new ArrayList<>();List<PromotionService.PricingLine> promoLines=new ArrayList<>();BigDecimal subtotal=BigDecimal.ZERO;
  for(CartItem item:items.findAllByCartIdOrderByCreatedAtAsc(cart.getId())){Product p=item.getProduct();ProductVariant v=item.getVariant();BigDecimal unit=money(v==null?p.effectivePrice():v.effectivePrice());BigDecimal line=unit.multiply(BigDecimal.valueOf(item.getQuantity())).setScale(2,RoundingMode.HALF_UP);SellableItemResolver.Inspection state=resolver.inspect(p,v,item.getQuantity());subtotal=subtotal.add(line);promoLines.add(new PromotionService.PricingLine(p,line));lines.add(new CartDtos.CartLine(item.getId(),p.getId(),v==null?null:v.getId(),p.getName(),v==null?p.getSku():v.getSku(),item.getQuantity(),unit,line,state.status(),state.availableQuantity(),item.getUpdatedAt()));}
  return new Pricing(List.copyOf(lines),money(subtotal),List.copyOf(promoLines));}
 private static BigDecimal money(BigDecimal v){return v.setScale(2,RoundingMode.HALF_UP);}private static ApiException invalidQuantity(){return error(HttpStatus.BAD_REQUEST,"INVALID_CART_QUANTITY","Cart quantity must be between 1 and 99.");}private static ApiException error(HttpStatus s,String c,String m){return new ApiException(s,c,m);}private record Pricing(List<CartDtos.CartLine> lines,BigDecimal subtotal,List<PromotionService.PricingLine> promotionLines){}public record CheckoutLine(CartItem cartItem,SellableItemResolver.Selection selection,BigDecimal unitPrice,BigDecimal lineSubtotal){}public record CheckoutSnapshot(Cart cart,List<CheckoutLine>lines,BigDecimal subtotal,BigDecimal merchandiseDiscount,BigDecimal discountedMerchandiseTotal,Promotion promotion,boolean freeShipping){}
}
